// One reminder 24 hours before and one 2 hours before each appointment, never twice for the same time.
// The customer's number is read from the event description, e.g. "Phone: +1234567890".
// Appointments the customer cancelled (red) are skipped. A moved appointment is reminded again.
const s = $('Your settings').first().json;
const sent = new Set($input.all().map(i => i.json).filter(r => r.eventId).map(r => r.eventId + '|' + r.type + '|' + r.details));
const now = Date.now();
const out = [];
for (const item of $('Get appointments in the next 25 hours').all()) {
  const e = item.json;
  if (e.status === 'cancelled' || e.colorId === '11' || !e.start || !e.start.dateTime) continue;
  const m = String(e.description || '').match(/(?:phone|tel|mobile|whatsapp)\s*[:\-]\s*(\+?[\d\s().-]{8,20})/i);
  if (!m) continue;
  const phone = m[1].replace(/\D/g, '');
  if (phone.length < 8) continue;
  const start = DateTime.fromISO(e.start.dateTime);
  const minutes = (start.toMillis() - now) / 60000;
  let type = null;
  if (minutes <= 120 && minutes > 15) type = '2h';
  else if (minutes <= 1440 && minutes > 180) type = '24h';
  const startIso = start.toUTC().toISO();
  if (!type || sent.has(e.id + '|' + type + '|' + startIso)) continue;
  const when = start.setZone(e.start.timeZone || s.timeZone).setLocale('en-GB').toFormat("cccc d LLLL 'at' HH:mm");
  const name = String(e.summary || '').split(' - ').pop().trim().split(' ')[0] || 'there';
  out.push({ json: { eventId: e.id, type, phone, name, when, startIso } });
}
return out;

// Button taps carry "CONFIRM|<eventId>", "RESCHEDULE|<eventId>" or "CANCEL|<eventId>" from the reminder template.
// Delivery and read receipts carry no message and stop here. One message is handled per run.
const data = $('WhatsApp message received').first().json;
const msg = (data.messages || [])[0];
if (!msg) return [];
const contact = (data.contacts || [])[0] || {};
const payload = (msg.button && msg.button.payload) || (msg.interactive && msg.interactive.button_reply && msg.interactive.button_reply.id) || '';
const [tap, eventId] = payload.split('|');
const actions = { CONFIRM: 'confirm', RESCHEDULE: 'reschedule', CANCEL: 'cancel' };
const tapped = Boolean(actions[tap] && eventId);
return [{
  json: {
    phone: msg.from,
    name: (contact.profile && contact.profile.name) || '',
    action: tapped ? actions[tap] : 'text',
    eventId: tapped ? eventId : '',
    text: (msg.text && msg.text.body) || (msg.button && msg.button.text) || '',
    isText: msg.type === 'text',
  },
}];

// A tap on a button already says what the customer wants. A typed 1, 2 or 3 picks one of the times
// offered in the last 48 hours. Other text goes to the model, but only for a number that was sent a
// reminder or an offer: every other chat on this number goes to the front desk unread by the model.
const reply = $('Read the message').first().json;
const rows = $input.all().map(i => i.json).filter(r => r.eventId);
const newest = (a, b) => String(b.sentAt).localeCompare(String(a.sentAt));
const reminder = rows.filter(r => r.type === '24h' || r.type === '2h').sort(newest)[0];
const offer = rows.filter(r => r.type === 'offer').sort(newest)[0];
let slots = [];
if (offer && Date.now() - new Date(offer.sentAt).getTime() < 48 * 3600 * 1000) {
  try { slots = JSON.parse(offer.details); } catch (e) { slots = []; }
}
if (!Array.isArray(slots)) slots = [];
const out = {
  ...reply,
  slot: null,
  offerEventId: slots.length ? offer.eventId : '',
  offerSlots: slots,
  offerText: slots.map((x, i) => (i + 1) + ') ' + x.label).join('\n'),
  needsModel: false,
  readBy: reply.action === 'text' ? 'rules' : 'button',
  summary: '',
};
if (reply.action === 'text') {
  const m = reply.text.trim().match(/^(?:option\s*|number\s*)?([1-3])[.)!]?$/i);
  if (m && slots[Number(m[1]) - 1]) {
    out.action = 'pick';
    out.slot = slots[Number(m[1]) - 1];
    out.eventId = offer.eventId;
  } else if (reply.isText && reply.text.trim() && (reminder || slots.length)) {
    out.eventId = slots.length ? offer.eventId : reminder.eventId;
    out.needsModel = true;
  } else {
    out.action = 'other';
  }
}
return [{ json: out, pairedItem: { item: 0 } }];

