// The model is asked for JSON. This node does not trust it: it parses safely, accepts only the five
// agreed intents, and turns anything doubtful into "other", which goes to the front desk.
const before = $('Work out what they mean').first().json;
const raw = String($json.text ?? $json.output ?? '').trim();
let parsed = null;
try {
  parsed = JSON.parse(raw.slice(raw.indexOf('{'), raw.lastIndexOf('}') + 1));
} catch (e) {
  parsed = null;
}
const ok = parsed && typeof parsed === 'object';
const allowed = ['confirm', 'reschedule', 'cancel', 'pick', 'other'];
let action = ok && allowed.includes(parsed.intent) ? parsed.intent : 'other';
const out = {
  ...before,
  needsModel: false,
  readBy: 'model',
  summary: ok ? String(parsed.summary || '').slice(0, 300) : 'The model did not answer in the agreed format.',
};
if (action === 'pick') {
  const slot = before.offerSlots[Number(parsed.choice) - 1];
  if (slot) {
    out.slot = slot;
    out.eventId = before.offerEventId;
  } else {
    action = 'other';
  }
}
if (action !== 'other' && !out.eventId) action = 'other';
out.action = action;
return [{ json: out, pairedItem: { item: 0 } }];

