parameters.jsCode:
// Up to three free times, the same length as the appointment, inside the opening hours from
// "Your settings", at most two on the same day. An event counts as busy unless it is cancelled,
// red (cancelled by the customer) or marked "Free". A busy all-day event closes that day.
const s = $('Your settings').first().json;
// This node is reached two ways: straight from "Reschedule", or again after a picked time turned out to be taken.
const again = $('Is the time still free?').isExecuted;
const reply = again ? $('Is the time still free?').first().json : $('Route by intent').first().json;
const appt = $('Get the appointment to move').first().json;
const tz = s.timeZone;
const start = DateTime.fromISO(appt.start.dateTime);
const minutes = Math.max(15, Math.round(DateTime.fromISO(appt.end.dateTime).diff(start, 'minutes').minutes));
const events = $input.all().map(i => i.json).filter(e => e.id && e.id !== appt.id && e.status !== 'cancelled' && e.colorId !== '11' && e.transparency !== 'transparent' && e.start);
const busy = events.filter(e => e.start.dateTime).map(e => [DateTime.fromISO(e.start.dateTime).toMillis(), DateTime.fromISO(e.end.dateTime).toMillis()]);
const closed = new Set();
for (const e of events.filter(e => e.start.date)) {
  for (let d = DateTime.fromISO(e.start.date, { zone: tz }); d < DateTime.fromISO(e.end.date, { zone: tz }); d = d.plus({ days: 1 })) closed.add(d.toISODate());
}
const workDays = String(s.workDays).split(',').map(x => Number(x.trim()));
const earliest = DateTime.now().plus({ hours: Number(s.minNoticeHours) });
const slots = [];
let day = DateTime.now().setZone(tz).startOf('day');
for (let d = 0; d <= Number(s.offerDays) && slots.length < 3; d++, day = day.plus({ days: 1 })) {
  if (!workDays.includes(day.weekday) || closed.has(day.toISODate())) continue;
  const close = day.set({ hour: Number(s.closeHour) });
  let t = day.set({ hour: Number(s.openHour) });
  let today = 0;
  while (t.plus({ minutes }) <= close && slots.length < 3 && today < 2) {
    const a = t.toMillis();
    const b = t.plus({ minutes }).toMillis();
    const free = t >= earliest && a !== start.toMillis() && !busy.some(([x, y]) => a < y && b > x);
    if (free) {
      slots.push({ start: t.toISO(), end: t.plus({ minutes }).toISO(), label: t.setLocale('en-GB').toFormat("cccc d LLLL 'at' HH:mm") });
      today++;
      t = t.plus({ minutes: Math.max(minutes, 120) });
    } else {
      t = t.plus({ minutes });
    }
  }
}
return [{
  json: {
    found: slots.length > 0,
    slots,
    offerText: slots.map((x, i) => (i + 1) + ') ' + x.label).join('\n'),
    intro: again ? 'Sorry, that time has just been taken. Here are the next free times:' : 'No problem. Here are the next free times:',
    eventId: appt.id,
    title: appt.summary || 'Appointment',
    was: start.setZone(tz).setLocale('en-GB').toFormat("cccc d LLLL 'at' HH:mm"),
    link: appt.htmlLink || '',
    phone: reply.phone,
    name: reply.name,
    summary: reply.summary,
  },
  pairedItem: { item: 0 },
}];

