// Between the offer and the answer someone else may have taken the time, so the calendar is read
// again for exactly that window. The appointment itself, cancelled and "Free" events do not count.
const reply = $('Route by intent').first().json;
const a = DateTime.fromISO(reply.slot.start).toMillis();
const b = DateTime.fromISO(reply.slot.end).toMillis();
const clash = $input.all().map(i => i.json).some(e => {
  if (!e.id || e.id === reply.eventId || e.status === 'cancelled' || e.colorId === '11' || e.transparency === 'transparent' || !e.start) return false;
  if (e.start.date) return true;
  return DateTime.fromISO(e.start.dateTime).toMillis() < b && DateTime.fromISO(e.end.dateTime).toMillis() > a;
});
return [{ json: { ...reply, free: !clash && a > Date.now() }, pairedItem: { item: 0 } }];

