// Tomorrow's appointments, each with where it stands. Green is confirmed, red is cancelled by the
// customer; the table says who was reminded and who was offered new times.
const s = $('Your settings').first().json;
const log = $input.all().map(i => i.json).filter(r => r.eventId);
const reminded = new Set(log.filter(r => r.type === '24h' || r.type === '2h').map(r => r.eventId));
const offered = new Set(log.filter(r => r.type === 'offer').map(r => r.eventId));
const groups = { 'No answer yet: worth a call': [], 'Asked for a new time, not chosen yet': [], 'No phone number on the event': [], 'Reminder not sent yet': [], 'Confirmed': [], 'Cancelled by the customer': [] };
let total = 0;
for (const item of $("Get tomorrow's appointments").all()) {
  const e = item.json;
  if (!e.id || e.status === 'cancelled' || !e.start || !e.start.dateTime) continue;
  total++;
  const m = String(e.description || '').match(/(?:phone|tel|mobile|whatsapp)\s*[:\-]\s*(\+?[\d\s().-]{8,20})/i);
  const line = DateTime.fromISO(e.start.dateTime).setZone(s.timeZone).toFormat('HH:mm') + '  ' + (e.summary || 'Appointment') + (m ? '  ' + m[1].trim() : '');
  let status = 'Reminder not sent yet';
  if (e.colorId === '11') status = 'Cancelled by the customer';
  else if (e.colorId === '10') status = 'Confirmed';
  else if (offered.has(e.id)) status = 'Asked for a new time, not chosen yet';
  else if (!m) status = 'No phone number on the event';
  else if (reminded.has(e.id)) status = 'No answer yet: worth a call';
  groups[status].push(line);
}
const day = DateTime.now().setZone(s.timeZone).plus({ days: 1 }).setLocale('en-GB').toFormat('cccc d LLLL');
const parts = Object.entries(groups).filter(([, lines]) => lines.length).map(([status, lines]) => status + ' (' + lines.length + ')\n' + lines.sort().join('\n'));
return [{
  json: {
    total,
    subject: 'Tomorrow, ' + day + ': ' + total + ' appointment' + (total === 1 ? '' : 's') + ', ' + groups['Confirmed'].length + ' confirmed, ' + groups['No answer yet: worth a call'].length + ' with no answer',
    body: parts.join('\n\n'),
  },
}];
